1|// Wheel-to-page-turn logic for the fixed-viewport reader. Pure, no React:
2|// the scene page feeds wheel events in and turns the page on "next"/"prev".
3|
4|export interface WheelTurnState {
5|  acc: number;
6|  lockedUntil: number;
7|  lastAt: number;
8|}
9|
10|export interface WheelTurnEvent {
11|  deltaY: number;
12|  deltaMode: number;
13|  now: number;
14|  atTop: boolean;
15|  atBottom: boolean;
16|}
17|
18|export type WheelTurnResult = "next" | "prev" | null;
19|
20|// WheelEvent deltaMode: 0 pixels, 1 lines, 2 pages.
21|const LINE_PX = 16;
22|const PAGE_PX = 800;
23|// Accumulated pixels that turn one page.
24|const TURN_PX = 60;
25|// A gap longer than this starts a fresh swipe.
26|const SWIPE_GAP_MS = 200;
27|// After a turn, ignore events until this long passes with no wheel events.
28|const LOCK_MS = 250;
29|
30|function toPixels(deltaY: number, deltaMode: number): number {
31|  if (deltaMode === 1) return deltaY * LINE_PX;
32|  if (deltaMode === 2) return deltaY * PAGE_PX;
33|  return deltaY;
34|}
35|
36|export function wheelTurn(
37|  state: WheelTurnState,
38|  e: WheelTurnEvent,
39|): { state: WheelTurnState; turn: WheelTurnResult } {
40|  if (e.now < state.lockedUntil) {
41|    // Trackpad inertia after a swipe: every event extends the lock, so one
42|    // swipe never turns twice. The lock ends only after a quiet gap.
43|    return { state: { acc: 0, lockedUntil: e.now + LOCK_MS, lastAt: e.now }, turn: null };
44|  }
45|  const dy = toPixels(e.deltaY, e.deltaMode);
46|  if (dy === 0) return { state: { ...state, lastAt: e.now }, turn: null };
47|  const down = dy > 0;
48|  if ((down && !e.atBottom) || (!down && !e.atTop)) {
49|    // The column still scrolls natively in this direction; let it.
50|    return { state: { acc: 0, lockedUntil: state.lockedUntil, lastAt: e.now }, turn: null };
51|  }
52|  const fresh =
53|    state.acc === 0 || Math.sign(state.acc) !== Math.sign(dy) || e.now - state.lastAt > SWIPE_GAP_MS;
54|  const acc = fresh ? dy : state.acc + dy;
55|  if (Math.abs(acc) >= TURN_PX) {
56|    return { state: { acc: 0, lockedUntil: e.now + LOCK_MS, lastAt: e.now }, turn: down ? "next" : "prev" };
57|  }
58|  return { state: { acc, lockedUntil: state.lockedUntil, lastAt: e.now }, turn: null };
59|}
60|
61|// Reading-column edges with a 2 px tolerance, so sub-pixel rounding and
62|// smooth-scroll landings still count as resting on the edge.
63|export function edges(el: HTMLElement): { atTop: boolean; atBottom: boolean } {
64|  const max = el.scrollHeight - el.clientHeight;
65|  return { atTop: el.scrollTop <= 2, atBottom: el.scrollTop >= max - 2 };
66|}
67|
68|export interface ReadOnInput {
69|  textIndex: number;
70|  textCount: number;
71|  hasEndPage: boolean;
72|  hasNextSceneInChapter: boolean;
73|  ch: number;
74|}
75|
76|// The continue cue under each text page: which label to show, or null to
77|// hide at the very end of the book.
78|export function readOnLabel(input: ReadOnInput): string | null {
79|  if (input.textIndex < input.textCount - 1) return "Turn the page ↓";
80|  if (input.hasEndPage) return `Finish Chapter ${input.ch} ↓`;
81|  if (input.hasNextSceneInChapter) return "Next scene ↓";
82|  return null;
83|}

